std::shared_future<Value> load(const Key& k, Loader& loader) {
  std::shared_ptr<std::promise<Value>> p; std::shared_future<Value> f;
  { std::lock_guard<std::mutex> lk(m_);
    auto it = m_.find(k);
    if (it != m_.end()) return it->second;              // join the flight
    p = std::make_shared<std::promise<Value>>();
    f = p->get_future().share();                        // one future, many readers
    m_.emplace(k, f);                                   // announce before running
  }                                                     // lock released
  try { p->set_value(loader(k)); }                      // leader runs once
  catch (...) { p->set_exception(std::current_exception()); }
  { std::lock_guard<std::mutex> lk(m_); m_.erase(k); }  // forget on completion
  return f;
}

