folly::ConcurrentHashMap<Key, folly::Future<Value>> m;
folly::Future<Value> load(const Key& k, Loader& loader) {
  auto it = m.find(k);
  if (it != m.end()) return it->second;             // join the flight
  auto p = std::make_shared<folly::SharedPromise<Value>>();
  auto ins = m.emplace(k, p->getFuture());          // many futures, one promise
  if (!ins.second) return ins.first->second;
  runAsync([p, k, &loader] { p->setWith([&] { return loader(k); }); })
      .ensure([&m, k] { m.erase(k); });             // forget on completion
  return ins.first->second;
}
